-- =============================================================================
-- MIGRATION: Create price_forecast_results table
-- Date: 2026-03-03
--
-- PURPOSE:
--   Stores every set of weekly price predictions generated by the app.
--   Each row is one forecast offset (week 1, 2, 3, 4) for a given
--   reference year/week/district tuple.
--
--   Written by PriceForecastScreen → saveForecastToSupabase()
--   after a successful /api/price-forecast/next-weeks call.
-- =============================================================================


-- ─────────────────────────────────────────────────────────────────────────────
-- 1.  TABLE
-- ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS price_forecast_results (
    id               BIGSERIAL    PRIMARY KEY,

    -- The week the farmer submitted the form
    ref_year         INT          NOT NULL,
    ref_week         INT          NOT NULL CHECK (ref_week BETWEEN 1 AND 52),
    district         TEXT         NOT NULL,
    season           TEXT         NOT NULL CHECK (season IN ('Maha', 'Yala')),

    -- Which predicted week this row covers (1 = next week … 4 = 4 weeks ahead)
    forecast_offset  INT          NOT NULL CHECK (forecast_offset BETWEEN 1 AND 52),

    -- Prediction output
    predicted_price  NUMERIC(10, 2) NOT NULL,
    confidence_pct   NUMERIC(5, 1),
    confidence_tag   TEXT         CHECK (confidence_tag IN ('High', 'Medium')),

    -- Reference price the farmer entered (used to compute deltas on re-read)
    farm_gate_price  NUMERIC(10, 2) NOT NULL,

    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now()
);

COMMENT ON TABLE  price_forecast_results               IS 'Per-week RF delta model predictions generated by the mobile app.';
COMMENT ON COLUMN price_forecast_results.ref_year      IS 'ISO calendar year of the forecast submission.';
COMMENT ON COLUMN price_forecast_results.ref_week      IS 'ISO week number at time of forecast.';
COMMENT ON COLUMN price_forecast_results.district      IS 'Farmer district (matches maize_prices.district).';
COMMENT ON COLUMN price_forecast_results.season        IS 'Maha or Yala season.';
COMMENT ON COLUMN price_forecast_results.forecast_offset IS '1 = week immediately ahead, 2 = two weeks ahead, etc.';
COMMENT ON COLUMN price_forecast_results.predicted_price IS 'Ensemble price predicted by RF delta model (Rs/kg).';
COMMENT ON COLUMN price_forecast_results.confidence_pct  IS 'Model confidence percentage (0–100).';
COMMENT ON COLUMN price_forecast_results.confidence_tag  IS '"High" or "Medium".';
COMMENT ON COLUMN price_forecast_results.farm_gate_price IS 'Actual price the farmer reported at submission time (lag_1 seed).';


-- ─────────────────────────────────────────────────────────────────────────────
-- 2.  INDEXES
-- ─────────────────────────────────────────────────────────────────────────────

-- Fast lookup: "show me all forecasts for Anuradhapura in 2025"
CREATE INDEX IF NOT EXISTS idx_pfr_district_year
    ON price_forecast_results (district, ref_year DESC, ref_week DESC);

-- Fast lookup: "show me all predictions for week 1 offsets"
CREATE INDEX IF NOT EXISTS idx_pfr_offset
    ON price_forecast_results (forecast_offset);


-- ─────────────────────────────────────────────────────────────────────────────
-- 3.  ROW-LEVEL SECURITY
-- ─────────────────────────────────────────────────────────────────────────────

ALTER TABLE price_forecast_results ENABLE ROW LEVEL SECURITY;

-- Anyone can read (unauthenticated mobile clients use anon key)
CREATE POLICY "pfr_public_read"
    ON price_forecast_results
    FOR SELECT
    USING (true);

-- Only service_role or authenticated admin can write
-- (The mobile app writes via the anon key which is covered by the
--  "authenticated" path when a user is logged in, or service_role from the server)
CREATE POLICY "pfr_authenticated_insert"
    ON price_forecast_results
    FOR INSERT
    WITH CHECK (
        auth.role() = 'service_role'
        OR auth.role() = 'authenticated'
    );
